-- 000776_travel_airports_results.up.sql
-- §67 Travel Search & Compare amendment:
--   * travel_airports — IATA airport catalog (OurAirports open dataset,
--     scheduled-service large/medium airports). Powers GET /travel/locations
--     so origin/destination pickers offer real flight locations.
--   * travel_search_results — persisted provider search results, one row per
--     unique canonical query, refreshed once expires_at passes. results stores
--     pre-affiliate payloads; affiliate params are stamped at serve time
--     (ADR-009).
--
-- Ref: japaconnect-engineering/sections/67-travel-search.md

BEGIN;

CREATE TABLE travel_airports (
    iata_code    text PRIMARY KEY,
    name         text NOT NULL,
    city         text NOT NULL,
    country_code text NOT NULL,
    latitude     double precision,
    longitude    double precision,
    airport_type text NOT NULL DEFAULT 'large'
        CHECK (airport_type IN ('large','medium'))
);

CREATE INDEX idx_travel_airports_city ON travel_airports (city text_pattern_ops);
CREATE INDEX idx_travel_airports_name ON travel_airports (name text_pattern_ops);

CREATE TABLE travel_search_results (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    search_type  text NOT NULL CHECK (search_type IN ('flight','hotel')),
    query_hash   text NOT NULL,
    params       jsonb NOT NULL,
    results      jsonb NOT NULL,
    provider_id  uuid REFERENCES travel_providers(id) ON DELETE SET NULL,
    fetched_at   timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL,
    hit_count    int  NOT NULL DEFAULT 0,
    CONSTRAINT travel_search_results_unique_query UNIQUE (search_type, query_hash)
);

CREATE INDEX idx_travel_search_results_expiry ON travel_search_results (expires_at);

